fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let steps = [4, 2, 1, 2, 4, 1];
    let radii = [36, 70, 104, 138, 172, 206];
    let sizes = [9, 7, 5, 4, 6, 3];
    let colors = [0xffd166, 0xef476f, 0x06d6a0, 0xffd166, 0xef476f, 0x06d6a0];
    host::display::clear(0x0a0510);
    let mut k: i32 = 0;
    while k < 6 {
        let stp: i32 = steps[k];
        let rad: i32 = radii[k];
        let sz: i32 = sizes[k];
        let rot: i32 = if (k & 1) == 0 { t / 6 } else { 0 - t / 6 };
        let mut j: i32 = 0;
        while j < 32 {
            let ai: i32 = (j + rot) & 31;
            let x: i32 = cx + tab[(ai + 8) & 31] * rad / 127;
            let y: i32 = cy + tab[ai] * rad / 127;
            host::display::fill_rect(x - sz / 2, y - sz / 2, sz, sz, colors[k]);
            j = j + stp;
        }
        k = k + 1;
    }
    host::display::draw_char(cx - 8, cy - 8, 42, 0xffd166, 2);
    host::display::present();
}
